import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, sin, dot, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'journal-title';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const disposables = [];
  const timelines = [];

  // ---------- STAGE BACKDROP ----------
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ toneMapped: true });

  const uvNode = uv();
  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  const gradientNode = mix(bottomColor, topColor, uvNode.y);

  // subtle static grain — no time dependency (static composition)
  const grainNoise = fract(
    sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = grainNoise.mul(0.025).sub(0.0125);
  backdropMat.colorNode = gradientNode.add(grain);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(() => backdropGeo.dispose(), () => backdropMat.dispose());

  // ---------- ATLAS ACCENT IMAGE PLANE (billboard sprite) ----------
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const imgHeight = 1.6;
  const imgWidth = imgHeight * aspect;

  const imgGeo = new THREE.PlaneGeometry(imgWidth, imgHeight);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.9 });
  const imagePlane = new THREE.Mesh(imgGeo, imgMat);
  imagePlane.position.set(0, 0.55, -1.0);
  imagePlane.name = 'journal-accent-sprite';
  group.add(imagePlane);
  disposables.push(() => imgGeo.dispose(), () => imgMat.dispose());

  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- HEADLINE TEXT ----------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? { text: 'Journal', typography: { fontSize: 96 } };

  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Journal', {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: colors.paper,
    align: 'center',
  });
  headline.position.set(0, -0.55, 0);
  group.add(headline);

  // ---------- ACCENT UNDERLINE (brand accent, small footprint) ----------
  const underlineGeo = new THREE.PlaneGeometry(1.1, 0.045);
  const underlineMat = new MeshBasicNodeMaterial({ transparent: true });
  underlineMat.colorNode = color(colors.accent);
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(0, -0.95, 0.05);
  group.add(underline);
  disposables.push(() => underlineGeo.dispose(), () => underlineMat.dispose());

  // ---------- ENTRANCE MOTION (weighted-settle, no perpetual motion) ----------
  group.position.y += 0.3;
  imgMat.opacity = 0;
  underlineMat.opacity = 0;
  headline.traverse((child) => {
    if (child.material) child.material.transparent = true;
  });

  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(group.position, { y: group.position.y - 0.3, duration: 0.7 }, 0);
  tl.to(imgMat, { opacity: 0.9, duration: 0.7 }, 0.05);
  tl.to(underlineMat, { opacity: 1, duration: 0.5 }, 0.35);
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  group.scale.set(0.96, 0.96, 0.96);
  timelines.push(tl);

  // ---------- HANDLERS (no interactions specified) ----------
  group.userData.handlers = {};

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((fn) => fn());
    if (loadedTex) loadedTex.dispose();
    headline.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (child.material.map) child.material.map.dispose();
        child.material.dispose();
      }
    });
  };

  return group;
}
